window.ATLAS_READY.then(() => {
'use strict';
const DB=window.ATLAS,all=DB.characters,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>{if(typeof v!=='string'||!v.trim())return '';try{const u=new URL(v,location.href);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}};
const fmt=n=>Number(n||0).toLocaleString('ko-KR'),compare=new Intl.Collator('ko').compare;
const name=c=>c.nameKorean||c.name,workName=w=>DB.labels?.works?.[w]||w,works=c=>c.displayWorks||c.works.map(workName);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const saved=new Set(read('character-atlas-saved',[])),notes=read('character-atlas-notes',{}),byId=new Map(all.map(c=>[c.id,c]));
const state={tab:'anime',query:'',work:'',tag:'',gender:'',period:'',role:'',kind:'',images:'',sort:'favorites',page:1,view:'grid'};
const SIZE=48,roleNames={MAIN:'주연',SUPPORTING:'조연',BACKGROUND:'배경 배역',UNKNOWN:'배역 미상'};
const tagName=t=>typeof t==='string'?t:t.name;
const shownTag=t=>tagName(t)+(['확인','공식 설정 확인','출처 확인','출처 명시'].includes(t.status)?'':'*');
const periods=c=>(c.workPeriods||[]).map(p=>typeof p==='string'?p:p.period).filter(p=>p>='2013-Q1'&&p<='2026-Q4');
const quarter=p=>p.replace(/(\d{4})-Q(\d)/,'$1년 $2분기');
const kind=c=>(c.variants?.length>1||c.battlesuits?.length>1)?'group':/unit|card|form|variant|카드|폼|변형|유닛/i.test(c.recordKind||c.recordType||'')?'variant':'entry';
const kindNames={entry:'개별 항목',variant:'카드·폼',group:'변형 묶음'};
const haystack=new Map(all.map(c=>[c.id,[name(c),c.name,c.nameOriginal,...c.aliases||[],...c.works,...works(c),...c.workAliases||[],...c.searchTerms||[],...c.tags.map(tagName)].join(' ').toLowerCase()]));
const researchBase=$('#research-link').getAttribute('href');
const scopes={anime:all.filter(c=>c.media==='anime'),game:all.filter(c=>c.media==='game'),all};
function scope(){return state.tab==='saved'?all.filter(c=>saved.has(c.id)):scopes[state.tab]||all;}
function savePersonal(){try{localStorage.setItem('character-atlas-saved',JSON.stringify([...saved]));localStorage.setItem('character-atlas-notes',JSON.stringify(notes));}catch{toast('이 브라우저에서는 개인 기록을 저장할 수 없습니다.');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2200);}
function options(id,values,label,display=v=>v){const el=$('#'+id);el.innerHTML='<option value="">'+esc(label)+'</option>'+[...new Set(values)].filter(Boolean).sort((a,b)=>compare(display(a),display(b))).map(v=>'<option value="'+esc(v)+'">'+esc(display(v))+'</option>').join('');el.value=state[id]||'';}
function resetFilters(){for(const key of ['query','work','tag','gender','period','role','kind','images']){state[key]='';const el=$('#'+key);if(el)el.value='';}state.page=1;}
function configureMenu(){const game=state.tab==='game',anime=state.tab==='anime',rows=scope();
 $('#work-label').textContent=game?'게임':'작품';options('work',rows.flatMap(c=>c.works),game?'전체 게임':'전체 작품',workName);options('tag',rows.flatMap(c=>c.tags.map(tagName)),'전체 속성');options('gender',rows.map(c=>c.gender),'전체 성별');options('period',rows.flatMap(periods),'전체 분기',quarter);
 $('#period-filter').hidden=game;$('#role-filter').hidden=!anime;$('#kind-filter').hidden=!game;
 $('#sort').innerHTML=(anime?'<option value="favorites">인기도순</option>':'')+'<option value="default">'+(game?'게임':'작품')+' · 이름순</option><option value="name">이름순</option><option value="tags">속성 많은 순</option>';state.sort=anime?'favorites':'default';$('#sort').value=state.sort;
 $('#query').placeholder=game?'캐릭터·게임·속성 검색':'캐릭터·작품·속성 검색';
 const gameShortcuts=['원신','붕괴: 스타레일','승리의 여신: 니케','블루 아카이브','명일방주','명조: 워더링 웨이브','Guardian Tales'];
 $('#context-menu').innerHTML=game?'<button data-game="" class="active">전체 게임</button>'+gameShortcuts.filter(w=>rows.some(c=>c.works.includes(w))).map(w=>'<button data-game="'+esc(w)+'">'+esc(workName(w))+'</button>').join(''):anime?'<button data-role="" class="active">전체 배역</button><button data-role="MAIN">주연</button><button data-role="SUPPORTING">조연</button>':'';
 $('#result-note').textContent=game?'· 카드·폼을 별도 항목으로 포함합니다.':'';
}
function setTab(tab){if(!['anime','game','all','saved','taxonomy'].includes(tab))tab='anime';state.tab=tab;resetFilters();document.body.dataset.section=tab;
 $$('#tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false');});
 const titles={anime:['애니메이션','주연부터 조연까지, 작품별로.','애니메이션 캐릭터 도감','이름, 작품, 모에속성으로 탐색하세요.'],game:['모바일 서브컬처','좋아하는 게임의 캐릭터를 한곳에.','모바일 수집형·가챠 캐릭터 도감','게임별 캐릭터와 카드·폼을 찾아보세요.'],all:['전체 캐릭터','애니와 게임을 함께 살펴보세요.','캐릭터 통합 도감','이름과 모에속성으로 새로운 캐릭터를 발견하세요.'],saved:['내 보관함','다시 보고 싶은 캐릭터들.','나만의 캐릭터 모음','별표로 보관하고 개인 메모를 남겨보세요.'],taxonomy:['모에속성 사전','취향을 찾는 다양한 단서.','모에속성 탐색','궁금한 속성을 고르면 해당 캐릭터를 볼 수 있습니다.']};
 const t=titles[tab];$('#page-title').innerHTML=esc(t[0])+'<span>'+esc(t[1])+'</span>';$('#eyebrow').textContent=t[2];$('#page-intro').textContent=t[3];$('#breadcrumb').textContent='캐릭터 아틀라스 / '+t[0];$('#collection').hidden=tab==='taxonomy';$('#taxonomy-panel').hidden=tab!=='taxonomy';
 const rows=scope();$('#hero-count').textContent=fmt(tab==='taxonomy'?DB.taxonomy.length:rows.length);$('#hero-label').textContent=tab==='game'?'게임 캐릭터·카드':tab==='taxonomy'?'탐색할 속성':'수록 캐릭터';$('#hero-unit').textContent=tab==='taxonomy'?'개의 속성':'개의 항목';$('#hero-meta').textContent=tab==='taxonomy'?'이름·외형·성격·관계별 분류':fmt(new Set(rows.flatMap(c=>c.works)).size)+'개 '+(tab==='game'?'게임':'작품')+' · '+fmt(rows.filter(c=>c.imageUrl).length)+'개 이미지';
 if(tab==='taxonomy')renderTaxonomy();else{configureMenu();render();}history.replaceState(null,'','#'+tab);
}
function filtered(){const q=state.query.trim().toLowerCase().split(/\s+/).filter(Boolean);return scope().filter(c=>(!state.work||c.works.includes(state.work))&&(!state.tag||c.tags.some(t=>tagName(t)===state.tag))&&(!state.gender||c.gender===state.gender)&&(!state.period||periods(c).includes(state.period))&&(!state.role||c.inclusion?.strongestRole===state.role)&&(!state.kind||kind(c)===state.kind)&&(!state.images||(state.images==='yes'?!!c.imageUrl:!c.imageUrl))&&q.every(w=>haystack.get(c.id).includes(w))).sort((a,b)=>{if(state.sort==='favorites'){const value=c=>c.id.startsWith('anime-anilist-')?Number(c.popularity?.value||0):-1;return value(b)-value(a)||compare(name(a),name(b));}if(state.sort==='tags')return b.tags.length-a.tags.length||compare(name(a),name(b));if(state.sort==='name')return compare(name(a),name(b));return compare(works(a)[0],works(b)[0])||compare(name(a),name(b));});}
function picture(c,eager=false){const original=safeUrl(c.originalImageUrl),url=safeUrl(c.imageAssetUrl)||(/^data:image\/(?:png|jpeg|webp|gif);base64,/.test(c.imageDataUrl||'')?c.imageDataUrl:'')||safeUrl(c.imageUrl)||original;return '<div class="image-fallback"><strong>'+esc(name(c).slice(0,1))+'</strong><small>이미지 없음</small></div>'+(url?'<img src="'+esc(url)+'"'+(c.imageUpgrade?.rule==='genshindev-exact-identity-portrait'?' class="illustration"':c.imageUpgrade?.rule==='guardian-korean-basic-illustration'?' class="guardian-art"':c.imageUpgrade?.rule==='namu-guardian-illustration'?' class="namu-illustration"':'')+(original&&original!==url?' data-fallback-src="'+esc(original)+'"':'')+' alt="'+esc(name(c))+'" loading="'+(eager?'eager':'lazy')+'" decoding="async" referrerpolicy="no-referrer">':'');}
function watchImages(root){root.querySelectorAll('img').forEach(img=>{
 if(img.dataset.watched)return;img.dataset.watched='true';
 const fallback=img.parentElement.querySelector('.image-fallback'),hint=img.closest('.detail-picture')?.querySelector('.image-quality-hint');
 const loaded=()=>{if(!img.naturalWidth||!img.naturalHeight){failed();return;}img.hidden=false;if(fallback)fallback.hidden=true;
  img.style.setProperty('--image-natural-width',img.naturalWidth+'px');img.style.setProperty('--image-natural-height',img.naturalHeight+'px');
  if(hint){const mobile=window.matchMedia('(max-width:750px)').matches,maxHeight=mobile?230:410,maxWidth=Math.min(img.parentElement.clientWidth,mobile?180:Infinity);hint.hidden=!(img.naturalWidth<maxWidth&&img.naturalHeight<maxHeight);}
 };
 const failed=()=>{const previous=safeUrl(img.dataset.fallbackSrc);if(previous&&!img.dataset.fallbackTried){img.dataset.fallbackTried='true';img.classList.remove('illustration','namu-illustration','guardian-art');img.hidden=false;img.src=previous;return;}img.hidden=true;if(fallback)fallback.hidden=false;if(hint)hint.hidden=true;};
 img.addEventListener('load',loaded);img.addEventListener('error',failed);if(img.complete){if(img.naturalWidth)loaded();else failed();}
});}
function tagButtons(c){return c.tags.slice(0,3).map(t=>'<button class="tag" data-tag="'+esc(tagName(t))+'">'+esc(shownTag(t))+'</button>').join('')+(c.tags.length>3?'<span class="tag">+'+(c.tags.length-3)+'</span>':'');}
function card(c){return '<article class="card"><div class="portrait '+(c.imageKind?.includes('배너')?'banner':'')+'" role="button" tabindex="0" data-open="'+esc(c.id)+'" aria-label="'+esc(name(c))+' 상세 보기">'+picture(c)+'<span class="media-pill">'+(c.media==='anime'?'애니':'게임')+'</span></div><button class="save '+(saved.has(c.id)?'saved':'')+'" data-save="'+esc(c.id)+'" aria-label="'+esc(name(c))+' 보관함" aria-pressed="'+saved.has(c.id)+'">'+(saved.has(c.id)?'★':'☆')+'</button><div class="card-info"><div class="work-name" title="'+esc(works(c).join(' · '))+'">'+esc(works(c)[0])+(c.works.length>1?' 외 '+(c.works.length-1)+'작품':'')+'</div><button class="name-button" data-open="'+esc(c.id)+'">'+esc(name(c))+'</button><div class="tags">'+(c.tags.length?tagButtons(c):'<span class="tag empty-tag">속성 미등록</span>')+'</div><div class="card-foot"><span>'+esc(c.gender||'성별 미상')+'</span><span>'+esc(c.media==='game'?kindNames[kind(c)]:roleNames[c.inclusion?.strongestRole]||'')+'</span></div></div></article>';}
function table(rows){return '<div class="table-wrap"><table class="records"><thead><tr><th>이미지</th><th>이름</th><th>작품</th><th>성별</th><th>모에속성</th></tr></thead><tbody>'+rows.map(c=>'<tr><td><div class="table-portrait">'+picture(c)+'</div></td><td><button class="name-button" data-open="'+esc(c.id)+'">'+esc(name(c))+'</button></td><td>'+esc(works(c).join(' · '))+'</td><td>'+esc(c.gender)+'</td><td>'+esc(c.tags.map(shownTag).join(' · ')||'미등록')+'</td></tr>').join('')+'</tbody></table></div>';}
function render(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/SIZE));state.page=Math.max(1,Math.min(state.page,pages));const page=rows.slice((state.page-1)*SIZE,state.page*SIZE);$('#result-count').textContent=fmt(rows.length);$('#cards').innerHTML=page.length?(state.view==='grid'?page.map(card).join(''):table(page)):'<div class="empty">조건에 맞는 캐릭터가 없습니다.<br>검색어 또는 필터를 바꿔보세요.</div>';$('#pagination').innerHTML='<button data-page="'+(state.page-1)+'" '+(state.page===1?'disabled':'')+'>← 이전</button><span>'+state.page+' / '+pages+'</span><button data-page="'+(state.page+1)+'" '+(state.page===pages?'disabled':'')+'>다음 →</button>';$('#nav-saved').textContent=fmt([...saved].filter(id=>byId.has(id)).length);if(state.tab==='saved')$('#hero-count').textContent=fmt(scope().length);$('#grid-mode').classList.toggle('active',state.view==='grid');$('#table-mode').classList.toggle('active',state.view==='table');watchImages($('#cards'));$('#context-menu').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.hasAttribute('data-game')?b.dataset.game===state.work:b.dataset.role===state.role));}
const imageViewer=document.createElement('dialog');imageViewer.id='image-viewer';imageViewer.setAttribute('aria-label','캐릭터 이미지 크게 보기');document.body.append(imageViewer);
imageViewer.addEventListener('click',e=>{if(e.target===imageViewer||e.target.closest('[data-close-image]'))imageViewer.close();});
function openImage(id){const c=byId.get(id);if(!c)return;imageViewer.innerHTML='<button class="image-viewer-close" data-close-image aria-label="큰 이미지 닫기">×</button><div class="image-viewer-picture">'+picture(c,true)+'</div><div class="image-viewer-name">'+esc(name(c))+'</div>';imageViewer.showModal();watchImages(imageViewer);}
document.addEventListener('click',e=>{const button=e.target.closest('[data-zoom-image]');if(button)openImage(button.dataset.zoomImage);});
function openDetail(id){const c=byId.get(id);if(!c)return;const names=works(c);const variants=c.variants||c.battlesuits||[];
 $('#detail-body').innerHTML='<div class="detail-grid"><aside class="detail-picture"><div class="detail-image">'+picture(c,true)+'</div>'+((c.imageDataUrl||c.imageUrl)?'<button class="image-expand" data-zoom-image="'+esc(c.id)+'">이미지 크게 보기</button>':'')+'<p class="image-quality-hint" hidden>작은 원본 이미지라 확대하지 않고 표시합니다.</p></aside><div class="detail-info"><div class="eyebrow">'+(c.media==='anime'?'애니메이션 캐릭터':'모바일 서브컬처 캐릭터')+'</div><h2>'+esc(name(c))+'</h2><p class="detail-sub">'+esc(names[0])+'</p><dl><dt>성별</dt><dd>'+esc(c.gender||'미상')+'</dd><dt>'+(c.media==='anime'?'배역':'형태')+'</dt><dd>'+esc(c.media==='anime'?roleNames[c.inclusion?.strongestRole]||'미상':kindNames[kind(c)])+'</dd></dl><h3>모에속성</h3><p class="note-hint">* 표시는 해석·추정이 포함된 속성입니다.</p><div class="detail-tags">'+(c.tags.length?c.tags.map(t=>'<span class="tag">'+esc(shownTag(t))+'</span>').join(''):'<p class="detail-sub">아직 등록된 속성이 없습니다.</p>')+'</div>'+(names.length>1?'<details class="work-list"><summary>전체 출연작 '+names.length+'개</summary><ul>'+names.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></details>':'')+(variants.length>1?'<details class="work-list"><summary>변형 '+variants.length+'개</summary><ul>'+variants.map(v=>'<li>'+esc(typeof v==='string'?v:v.nameKorean||v.name||v.title||'이름 미상')+'</li>').join('')+'</ul></details>':'')+'<h3>개인 메모</h3><textarea class="local-note" id="personal-note" data-id="'+esc(id)+'" placeholder="기억해 둘 내용을 적어보세요.">'+esc(notes[id]||'')+'</textarea><p class="note-hint">이 브라우저에 자동 저장됩니다.</p><div class="detail-actions"><button class="solid" data-save="'+esc(id)+'">'+(saved.has(id)?'보관함에서 빼기':'보관함에 넣기')+'</button><a class="research-link" target="_blank" rel="noopener" href="'+esc(researchBase)+'#character='+encodeURIComponent(id)+'">자료실에서 원본·출처 보기 ↗</a></div></div></div>';$('#detail').showModal();watchImages($('#detail-body'));$('#detail').scrollTop=0;}
function renderTaxonomy(){const q=$('#taxonomy-query').value.toLowerCase(),terms=DB.taxonomy.filter(t=>[t.name,t.description,t.category,...t.aliases||[]].join(' ').toLowerCase().includes(q));$('#taxonomy-list').innerHTML=[...new Set(terms.map(t=>t.category))].map(category=>'<div class="taxonomy-group"><h2>'+esc(category)+'</h2><div class="term-grid">'+terms.filter(t=>t.category===category).map(t=>'<article class="term"><button data-tag="'+esc(t.name)+'">캐릭터 보기 →</button><h3>'+esc(t.name)+'</h3><p>'+esc(t.description)+'</p></article>').join('')+'</div></div>').join('')||'<div class="empty">검색 결과가 없습니다.</div>';}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
$('#export').onclick=()=>{const rows=filtered(),headers=['식별자','이름','작품','구분','성별','모에속성','이미지 주소','개인 메모'];download('캐릭터-목록.csv','\uFEFF'+[headers,...rows.map(c=>[c.id,name(c),works(c).join(' | '),c.media==='anime'?'애니메이션':'모바일 서브컬처',c.gender,c.tags.map(tagName).join(' | '),safeUrl(c.imageAssetUrl||c.imageUrl),notes[c.id]||''])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast(fmt(rows.length)+'개 항목을 내려받았습니다.');};
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-open]');if(!el)return;if(el.dataset.tab)setTab(el.dataset.tab);if(el.dataset.open)openDetail(el.dataset.open);if(el.dataset.save){const id=el.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);savePersonal();render();if($('#detail').open){el.textContent=saved.has(id)?'보관함에서 빼기':'보관함에 넣기';}}if(el.dataset.tag){const tag=el.dataset.tag;if(state.tab==='taxonomy')setTab('all');state.tag=tag;$('#tag').value=tag;state.page=1;render();}if(el.hasAttribute('data-game')){state.work=el.dataset.game;$('#work').value=state.work;state.page=1;render();}if(el.hasAttribute('data-role')){state.role=el.dataset.role;$('#role').value=state.role;state.page=1;render();}if(el.dataset.page){state.page=Number(el.dataset.page);render();$('.results-line').scrollIntoView({behavior:'smooth'});}});
let timer;$('#query').addEventListener('input',e=>{state.query=e.target.value;state.page=1;clearTimeout(timer);timer=setTimeout(render,100);});
for(const key of ['work','tag','gender','period','role','kind','images','sort'])$('#'+key).addEventListener('change',e=>{state[key]=e.target.value;state.page=1;render();});
$('#reset').onclick=()=>{resetFilters();render();};$('#grid-mode').onclick=()=>{state.view='grid';render();};$('#table-mode').onclick=()=>{state.view='table';render();};$('#close-detail').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();});$('#detail').addEventListener('input',e=>{if(e.target.id==='personal-note'){notes[e.target.dataset.id]=e.target.value;savePersonal();}});$('#taxonomy-query').addEventListener('input',renderTaxonomy);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#detail').open){e.preventDefault();if(state.tab==='taxonomy')setTab('all');$('#query').focus();}if(['Enter',' '].includes(e.key)&&e.target.matches('.portrait')){e.preventDefault();openDetail(e.target.dataset.open);}});
$('#nav-anime').textContent=fmt(scopes.anime.length);$('#nav-game').textContent=fmt(scopes.game.length);$('#nav-all').textContent=fmt(all.length);setTab(location.hash.slice(1)||'anime');
}).catch(error=>{document.querySelector('#hero-meta').textContent='데이터를 열지 못했습니다: '+error.message;console.error(error);});
